package ph.printshop.pos;

import android.database.sqlite.SQLiteDatabase;

/**
 * Isolated SQL candidate for a unified cash chain. Requires ReceivableJournal candidate first.
 * Do NOT call from production migrations until authoritative credit checkout and report integration.
 */
final class CreditCashJournal {
    private CreditCashJournal(){}
    static void createCandidate(SQLiteDatabase db){
        db.execSQL("CREATE TABLE cashier_cash_effects_v2 (event_no INTEGER PRIMARY KEY AUTOINCREMENT CHECK(event_no>=1), shift_id TEXT NOT NULL REFERENCES cashier_shifts(id), legacy_event_no INTEGER UNIQUE REFERENCES cashier_drawer_effects(event_no), credit_id TEXT UNIQUE REFERENCES credit_receivable_sources(id), collection_id TEXT UNIQUE REFERENCES credit_collection_requests(id), before_cash INTEGER NOT NULL CHECK(typeof(before_cash)='integer' AND before_cash BETWEEN 0 AND 9999999999900000), after_cash INTEGER NOT NULL CHECK(typeof(after_cash)='integer' AND after_cash BETWEEN 0 AND 9999999999900000), recorded_ms INTEGER NOT NULL CHECK(typeof(recorded_ms)='integer' AND recorded_ms>=0), CHECK((legacy_event_no IS NOT NULL)+(credit_id IS NOT NULL)+(collection_id IS NOT NULL)=1))");
        db.execSQL("CREATE INDEX cash_v2_chain ON cashier_cash_effects_v2(shift_id,event_no DESC)");
        // Preserve every existing effect and its original order. The original audit is never replaced.
        db.execSQL("INSERT INTO cashier_cash_effects_v2(event_no,shift_id,legacy_event_no,before_cash,after_cash,recorded_ms) SELECT event_no,shift_id,event_no,before_cash,after_cash,recorded_ms FROM cashier_drawer_effects ORDER BY event_no");
        db.execSQL("DROP VIEW cashier_drawer_current");
        db.execSQL("CREATE VIEW cashier_drawer_current AS SELECT a.shift_id,COALESCE((SELECT e.after_cash FROM cashier_cash_effects_v2 e WHERE e.shift_id=a.shift_id ORDER BY e.event_no DESC LIMIT 1),a.baseline_cash) AS expected_cash FROM cashier_drawer_anchors a");
        db.execSQL("CREATE TRIGGER cash_v2_effect_insert BEFORE INSERT ON cashier_cash_effects_v2 WHEN EXISTS(SELECT 1 FROM cashier_cash_effects_v2 e WHERE e.event_no=NEW.event_no OR e.legacy_event_no=NEW.legacy_event_no OR e.credit_id=NEW.credit_id OR e.collection_id=NEW.collection_id) OR NOT EXISTS(SELECT 1 FROM cashier_shifts s JOIN cashier_drawer_current b ON b.shift_id=s.id WHERE s.id=NEW.shift_id AND s.state='OPEN' AND b.expected_cash=NEW.before_cash) OR (NEW.legacy_event_no IS NOT NULL AND NOT EXISTS(SELECT 1 FROM cashier_drawer_effects e WHERE e.event_no=NEW.legacy_event_no AND e.shift_id=NEW.shift_id AND e.before_cash=NEW.before_cash AND e.after_cash=NEW.after_cash AND e.recorded_ms=NEW.recorded_ms)) OR (NEW.credit_id IS NOT NULL AND NOT EXISTS(SELECT 1 FROM credit_receivable_sources d WHERE d.id=NEW.credit_id AND d.shift_id=NEW.shift_id AND d.paid>0 AND NEW.after_cash=NEW.before_cash+d.paid AND NEW.recorded_ms=d.opened_ms)) OR (NEW.collection_id IS NOT NULL AND NOT EXISTS(SELECT 1 FROM credit_collection_requests c WHERE c.id=NEW.collection_id AND c.shift_id=NEW.shift_id AND c.state='APPLIED' AND c.before_cash=NEW.before_cash AND c.after_cash=NEW.after_cash AND c.resolved_ms=NEW.recorded_ms)) BEGIN SELECT RAISE(ABORT,'Invalid unified cash effect'); END");
        db.execSQL("CREATE TRIGGER cash_v2_effect_no_update BEFORE UPDATE ON cashier_cash_effects_v2 BEGIN SELECT RAISE(ABORT,'Unified cash effect immutable'); END");
        db.execSQL("CREATE TRIGGER cash_v2_effect_no_delete BEFORE DELETE ON cashier_cash_effects_v2 BEGIN SELECT RAISE(ABORT,'Unified cash effect immutable'); END");
        db.execSQL("CREATE TRIGGER cash_v2_legacy_mirror AFTER INSERT ON cashier_drawer_effects BEGIN INSERT INTO cashier_cash_effects_v2(shift_id,legacy_event_no,before_cash,after_cash,recorded_ms) VALUES(NEW.shift_id,NEW.event_no,NEW.before_cash,NEW.after_cash,NEW.recorded_ms); SELECT CASE WHEN changes()<>1 THEN RAISE(ABORT,'Legacy cash mirror missing') END; END");
        db.execSQL("CREATE TRIGGER cash_v2_credit_guard BEFORE INSERT ON credit_receivable_sources WHEN NOT EXISTS(SELECT 1 FROM cashier_drawer_current b WHERE b.shift_id=NEW.shift_id AND b.expected_cash+NEW.paid<=9999999999900000) OR EXISTS(SELECT 1 FROM credit_collection_requests c WHERE c.shift_id=NEW.shift_id AND c.state='PENDING') OR EXISTS(SELECT 1 FROM cashier_drawer_requests r WHERE r.shift_id=NEW.shift_id AND r.state='PENDING') OR EXISTS(SELECT 1 FROM cashier_shift_checkouts l JOIN checkout_requests r ON r.request_id=l.request_id WHERE l.shift_id=NEW.shift_id AND r.state='PENDING') BEGIN SELECT RAISE(ABORT,'Credit cash review blocked'); END");
        db.execSQL("CREATE TRIGGER cash_v2_credit_apply AFTER INSERT ON credit_receivable_sources WHEN NEW.paid>0 BEGIN INSERT INTO cashier_cash_effects_v2(shift_id,credit_id,before_cash,after_cash,recorded_ms) SELECT NEW.shift_id,NEW.id,b.expected_cash,b.expected_cash+NEW.paid,NEW.opened_ms FROM cashier_drawer_current b WHERE b.shift_id=NEW.shift_id; SELECT CASE WHEN changes()<>1 THEN RAISE(ABORT,'Credit cash effect missing') END; END");
        db.execSQL("CREATE TRIGGER cash_v2_collection_apply AFTER UPDATE ON credit_collection_requests WHEN NEW.state='APPLIED' BEGIN INSERT INTO cashier_cash_effects_v2(shift_id,collection_id,before_cash,after_cash,recorded_ms) VALUES(NEW.shift_id,NEW.id,NEW.before_cash,NEW.after_cash,NEW.resolved_ms); SELECT CASE WHEN changes()<>1 THEN RAISE(ABORT,'Collection cash effect missing') END; END");
        // Symmetric conflict guards; original triggers continue enforcing legacy invariants.
        db.execSQL("CREATE TRIGGER cash_v2_pending_drawer BEFORE INSERT ON cashier_drawer_requests WHEN EXISTS(SELECT 1 FROM credit_collection_requests c WHERE c.shift_id=NEW.shift_id AND c.state='PENDING') BEGIN SELECT RAISE(ABORT,'Resolve pending collection first'); END");
        db.execSQL("CREATE TRIGGER cash_v2_pending_checkout BEFORE INSERT ON cashier_shift_checkouts WHEN EXISTS(SELECT 1 FROM credit_collection_requests c WHERE c.shift_id=NEW.shift_id AND c.state='PENDING') OR EXISTS(SELECT 1 FROM credit_receivable_sources d WHERE d.id=NEW.request_id) BEGIN SELECT RAISE(ABORT,'Pending collection or credit identity collision'); END");
        db.execSQL("CREATE TRIGGER cash_v2_pending_close BEFORE UPDATE ON cashier_shifts WHEN NEW.state='CLOSED' AND EXISTS(SELECT 1 FROM credit_collection_requests c WHERE c.shift_id=OLD.id AND c.state='PENDING') BEGIN SELECT RAISE(ABORT,'Resolve pending collection before close'); END");
        // Report components are discriminated: sale total != cash received; collection is never gross revenue.
        db.execSQL("CREATE VIEW credit_report_events AS SELECT 'CREDIT_SALE' AS kind,id AS source_id,shift_id,opened_ms AS recorded_ms,total AS gross,paid AS cash_received,total-paid AS debt_created,0 AS debt_collected FROM credit_receivable_sources UNION ALL SELECT 'COLLECTION',id,shift_id,resolved_ms,0,amount,0,amount FROM credit_collection_requests WHERE state='APPLIED'");
    }
}
